import { test } from 'bun:test';
import assert from 'node:assert';
import { isBrokenShim, isShim, needsRepair, shimContent, shimFileName, shimTargets } from '../node/cliShims';

// A shim as extension 1.0.0 wrote it from Devin Desktop, whose copy of the extension
// was removed afterwards.
const DEVIN_SHIM = `#!/bin/sh
# Generated by the OMNeT++ VS Code extension; rewritten when the extension is updated.
script='/home/u/.devin/extensions/opensim.omnetpp-vscode-1.0.0/dist/opp_lint.js'
runtime='/home/u/.local/bin/Devin/devin-desktop'
if [ ! -f "$script" ] || [ ! -x "$runtime" ]; then echo 'opp_lint: the OMNeT++ VS Code extension or VS Code was updated or removed. Run "OMNeT++: Install Command-Line Tools" again.' >&2; exit 127; fi
ELECTRON_RUN_AS_NODE=1 exec "$runtime" "$script" "$@"
`;

test('the paths of an existing shim are read back, also from shims of earlier versions', () => {
  assert.deepEqual(shimTargets(DEVIN_SHIM), {
    script: '/home/u/.devin/extensions/opensim.omnetpp-vscode-1.0.0/dist/opp_lint.js',
    runtime: '/home/u/.local/bin/Devin/devin-desktop',
  });
});

test('sh and cmd shims give back the paths they were written with', () => {
  const sh = { script: "/home/o'brien/ext dir/dist/opp_lint.js", runtime: '/usr/share/code/code' };
  assert.deepEqual(shimTargets(shimContent('opp_lint', sh.runtime, sh.script, 'linux')), sh);
  const cmd = {
    script: 'C:\\Users\\A B\\.vscode\\extensions\\opensim.omnetpp-vscode-1.0.1\\dist\\opp_lint.js',
    runtime: 'C:\\Users\\A B\\AppData\\Local\\Programs\\Microsoft VS Code\\Code.exe',
  };
  assert.deepEqual(shimTargets(shimContent('opp_lint', cmd.runtime, cmd.script, 'win32')), cmd);
});

test('a shim is broken when its script or its runtime is gone', () => {
  const live = new Set(['/home/u/.local/bin/Devin/devin-desktop']);
  assert.equal(isBrokenShim(DEVIN_SHIM, (p) => live.has(p)), true);
  live.add('/home/u/.devin/extensions/opensim.omnetpp-vscode-1.0.0/dist/opp_lint.js');
  assert.equal(isBrokenShim(DEVIN_SHIM, (p) => live.has(p)), false);
  live.delete('/home/u/.local/bin/Devin/devin-desktop');
  assert.equal(isBrokenShim(DEVIN_SHIM, (p) => live.has(p)), true);
});

test('files the extension did not write are never broken shims', () => {
  const npmShim = '#!/bin/sh\nexec node "$basedir/../lib/node_modules/@omnetpp/opp-tools/dist/opp_lint.js" "$@"\n';
  assert.equal(isShim(npmShim), false);
  assert.equal(isBrokenShim(npmShim, () => false), false);
  assert.equal(isShim(DEVIN_SHIM), true);
});

test('the stale-shim hint names both ways to get working tools', () => {
  for (const platform of ['linux', 'win32'] as const) {
    const text = shimContent('opp_lint', '/r', '/s.js', platform);
    assert.match(text, /Install Command-Line Tools/);
    assert.match(text, /npm install -g @omnetpp\/opp-tools/);
  }
  // cmd.exe echoes the hint inside a parenthesized block
  const hint = /\(echo (.*) 1>&2 & exit \/b 127\)/.exec(shimContent('opp_lint', '/r', '/s.js', 'win32'))![1];
  assert.doesNotMatch(hint, /[()&|<>^%]/);
  assert.equal(shimFileName('opp_lint', 'win32'), 'opp_lint.cmd');
  assert.equal(shimFileName('opp_lint', 'darwin'), 'opp_lint');
});

const VSCODE = { script: '/ext/vscode-1.0.1/dist/opp_lint.js', runtime: '/usr/share/code/code' };
const CURSOR = { script: '/ext/cursor-1.0.1/dist/opp_lint.js', runtime: '/opt/cursor/cursor' };
const shim = (t: { script: string; runtime: string }) => shimContent('opp_lint', t.runtime, t.script, 'linux');
const all = () => true;

test('an editor without an install record repairs the shims another editor left broken', () => {
  const devinGone = (p: string) => !p.includes('.devin');
  assert.equal(needsRepair(DEVIN_SHIM, devinGone, VSCODE), true);
});

test('working shims of another editor are left alone', () => {
  assert.equal(needsRepair(shim(CURSOR), all, VSCODE), false);
  assert.equal(needsRepair(shim(CURSOR), all, VSCODE, { ...VSCODE, script: '/ext/vscode-1.0.0/dist/opp_lint.js' }), false);
});

test('after an update an editor follows the shims of its previous install, while the old copy still exists', () => {
  const previous = { ...VSCODE, script: '/ext/vscode-1.0.0/dist/opp_lint.js' };
  assert.equal(needsRepair(shim(previous), all, VSCODE, previous), true);
  assert.equal(needsRepair(shim(VSCODE), all, VSCODE, VSCODE), false);
});

test('a tool the user replaced is never repaired', () => {
  assert.equal(needsRepair('#!/bin/sh\nexec node /npm/opp_lint.js "$@"\n', () => false, VSCODE), false);
});
